    25          jq_start(jq, input, 0);
    26          jv next = jv_parse(parse_payload2.c_str());
    27          if (jv_is_valid(next)) {
    28            jv actual = jq_next(jq);
    29            jv_free(actual);
    30          }
    31          jv_free(next);
    32        } else {
    33          // Only free if input is invalid as otherwise jq_teardown
    34          // frees it.
    35          jv_free(input);
    36        }
    37      }
    38    }
    39    jq_teardown(&jq);
    40
    41    return 0;
    42  }
